        {
            "code": "PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_1",
            "message": "Vous fournissez ces données via l’utilisation de l’application mobile",
            "module": "digit-privacy-policy",
            "locale": "fr_MZ"
        },
        {
            "code": "PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_2",
